## Code Example
```javascript
// Azure Function (JS) sketch: read EventHub message and write to Cosmos with tenant partition
module.exports = async function(context, messages){
  for (const m of messages){
    const item = { id: m.id, tenantId: m.tenantId, ...m.payload };
    await cosmosContainer.items.upsert(item);
  }
}
